template <bool v>
struct bool_c {
    static constexpr bool value = v;
};

// Generic trait negation wrapper
template <typename Trait>
struct Negate : bool_c<!Trait::value> {};

// --- Example Trait to Negate ---
template <typename T> struct is_pointer_like : bool_c<false> {};
template <typename T> struct is_pointer_like<T*> : bool_c<true> {};

// Usage
using TraitA = is_pointer_like<int*>;          // true
using TraitNotA = Negate<TraitA>;             // false

// Compile-time result check
constexpr bool result = TraitNotA::value;      // result == false
